import sys

def patch_file(path, old, new, label):
    with open(path, 'r', encoding='utf-8') as f:
        content = f.read()
    count = content.count(old)
    if count == 0:
        print(f'  [SKIP/FAIL] {label}: old string not found in {path}. '
              f'Already patched, or file differs -- check manually.')
        return
    if count > 1:
        print(f'  [WARN] {label}: found {count} times in {path}, expected 1.')
    content = content.replace(old, new)
    with open(path, 'w', encoding='utf-8') as f:
        f.write(content)
    print(f'  [OK] {label}: applied to {path}')

print('Patching brokers/upstox.py (place_gtt_trailing_sl full rewrite)...')
patch_file('brokers/upstox.py', '    async def place_gtt_trailing_sl(\n        self,\n        instrument_key: str,\n        quantity: int,\n        entry_price: float,\n        order_type: str = "SELL",  # "SELL" means we sold, so exit is BUY\n        trailing_gap: float = 0.25,\n        sl_pct: float = 0.15,      # SL at 15% above entry (for SELL trade)\n    ) -> str:\n        try:\n            import upstox_client\n            cfg = upstox_client.Configuration()\n            cfg.access_token = self.access_token\n            client = upstox_client.ApiClient(cfg)\n\n            exit_transaction = "BUY" if order_type == "SELL" else "SELL"\n            trigger_price = round(entry_price * (1 + sl_pct), 1)\n\n            rule = upstox_client.GttRule(\n                strategy="TRAILING_STOP_LOSS",\n                trigger_type="RISING",\n                trigger_price=trigger_price,\n                trailing_gap=trailing_gap,\n                market_protection=0.25,\n            )\n\n            req = upstox_client.GttPlaceOrderRequest(\n                type="SINGLE",\n                quantity=quantity,\n                product="I",\n                rules=[rule],\n                instrument_token=instrument_key,\n                transaction_type=exit_transaction,\n            )\n\n            gtt_api = upstox_client.GttApi(client)\n            resp = gtt_api.place_gtt_order(req, api_version="2.0")\n            gtt_id = resp.data.id if resp and resp.data else ""\n            import logging\n            logging.getLogger(__name__).info(\n                f"[GTT] Trailing SL placed | {instrument_key} | "\n                f"trigger={trigger_price} | trailing_gap={trailing_gap} | id={gtt_id}"\n            )\n            return str(gtt_id)\n        except Exception as e:\n            import logging\n            logging.getLogger(__name__).warning(f"[GTT] Failed to place GTT: {e}")\n            return ""\n', '    async def place_gtt_trailing_sl(\n        self,\n        instrument_key: str,\n        quantity: int,\n        entry_price: float,\n        order_type: str = "SELL",  # "SELL" = we sold (short), exit is BUY.\n                                    # "BUY"  = we bought (long), exit is SELL.\n        trailing_gap: float = 0.25,\n        sl_pct: float = 0.15,       # SL distance from entry, direction depends on order_type\n    ) -> str:\n        """\n        CRITICAL BUGFIX 2026-09: this function has never successfully placed a\n        real GTT order, in any direction, live or otherwise, since it was\n        written. Verified directly against the installed upstox_client SDK\n        (upstox-python-sdk==2.29.0). It had FOUR independent bugs, any one of\n        which alone would have been fatal:\n\n        1. GttRule.strategy only accepts ["ENTRY", "STOPLOSS", "TARGET"].\n           Old code passed "TRAILING_STOP_LOSS" -- invalid, raises ValueError\n           the instant GttRule() is constructed, before any network call.\n\n        2. GttRule.trigger_type only accepts ["ABOVE", "BELOW", "IMMEDIATE"].\n           Old code passed "RISING" -- also invalid, same failure mode.\n           (For a standalone STOPLOSS-only leg -- no ENTRY leg, since we\n           already hold the position -- the correct value is always\n           "IMMEDIATE": the leg is live the moment it\'s placed, and\n           trigger_price alone determines whether it needs price to rise or\n           fall to fire. ABOVE/BELOW is for a GTT\'s ENTRY leg, which waits\n           for price to cross a threshold before an order is even placed --\n           doesn\'t apply here. Confirmed against Upstox\'s own official\n           sample code for a standalone stop-loss GTT: GttRule(strategy=\n           "STOPLOSS", trigger_type="IMMEDIATE", trigger_price=...).)\n\n        3. There is no `GttApi` class in this SDK version at all -- GTT\n           order placement lives on `OrderApiV3` (imported here as\n           `upstox_client.OrderApiV3`, already instantiated once in login()\n           as `self._order_api` -- reused here rather than constructing a\n           fresh client). `upstox_client.GttApi(client)` would have raised\n           AttributeError. Also, `place_gtt_order()` takes no `api_version`\n           kwarg (unlike `get_profile`, which does) -- passing one raises\n           TypeError.\n\n        4. The response\'s actual shape is `resp.data.gtt_order_ids` (a\n           list[str]), not `resp.data.id`. Old code\'s `resp.data.id` would\n           have raised AttributeError had it ever gotten this far.\n\n        Net effect: every previous call to this function failed at bug #1\n        or #2, was caught by the broad except below, logged as "Failed to\n        place GTT", and returned "". survivor.py\'s retry-then-alert-then-\n        auto-close fallback (if reached with a live SELL fill) would\n        therefore always have fired -- or if never reached, GTTs were\n        simply never armed at all despite the code appearing to do so.\n\n        Direction handling (unchanged from the previous fix, still correct):\n          SELL entry (short) -> exit BUY  | trigger_price = entry*(1+sl_pct)\n          BUY  entry (long)  -> exit SELL | trigger_price = entry*(1-sl_pct)\n        """\n        try:\n            if order_type == "SELL":\n                exit_transaction = "BUY"\n                trigger_price     = round(entry_price * (1 + sl_pct), 1)\n            elif order_type == "BUY":\n                exit_transaction = "SELL"\n                trigger_price     = round(entry_price * (1 - sl_pct), 1)\n            else:\n                raise ValueError(f"place_gtt_trailing_sl: unsupported order_type={order_type!r}")\n\n            rule = upstox_client.GttRule(\n                strategy="STOPLOSS",\n                trigger_type="IMMEDIATE",\n                trigger_price=trigger_price,\n                trailing_gap=trailing_gap,\n                market_protection=0.25,\n            )\n\n            req = upstox_client.GttPlaceOrderRequest(\n                type="SINGLE",\n                quantity=quantity,\n                product="I",\n                rules=[rule],\n                instrument_token=instrument_key,\n                transaction_type=exit_transaction,\n            )\n\n            resp = self._order_api.place_gtt_order(req)\n            gtt_ids = resp.data.gtt_order_ids if resp and resp.data else []\n            gtt_id = gtt_ids[0] if gtt_ids else ""\n            logger.info(\n                f"[GTT] Trailing SL placed | {instrument_key} | order_type={order_type} | "\n                f"trigger={trigger_price} | trailing_gap={trailing_gap} | id={gtt_id}"\n            )\n            return str(gtt_id)\n        except Exception as e:\n            logger.warning(f"[GTT] Failed to place GTT: {e}")\n            return ""\n', 'place_gtt_trailing_sl full rewrite')

print('Patching strategy/base_strategy.py (add _arm_broker_stop_loss helper)...')
patch_file('strategy/base_strategy.py', '        # Fallback: treat every Tuesday as expiry (Nifty weekly expiry)\n        return datetime.now().weekday() == 1', '        # Fallback: treat every Tuesday as expiry (Nifty weekly expiry)\n        return datetime.now().weekday() == 1\n\n    async def _arm_broker_stop_loss(\n        self,\n        ikey: str,\n        quantity: int,\n        entry_price: float,\n        symbol: str,\n        on_failure=None,\n        sl_pct: float = 0.15,\n        trailing_gap: float = 0.25,\n        order_type: str = "SELL",\n    ) -> bool:\n        """\n        Shared broker-side GTT trailing stop-loss arming, lifted from the\n        pattern already proven in survivor.py (Phase 2 of the audit fixes,\n        2026-09).\n\n        `order_type` must match the entry direction of the POSITION being\n        protected, not necessarily "SELL": pass "SELL" for a short-option\n        entry (exit is BUY, stop triggers on a price rise) and "BUY" for a\n        long-option entry (exit is SELL, stop triggers on a price fall) --\n        see brokers/upstox.py\'s place_gtt_trailing_sl for the direction\n        logic. Defaulting to "SELL" matches every strategy wired so far\n        except nifty_gex, which holds long options and must pass "BUY"\n        explicitly.\n\n        This is a BACKSTOP, not the primary exit mechanism -- each strategy\'s\n        own tick-driven software SL/trailing-profit logic should still fire\n        first under normal conditions and is expected to win that race. The\n        GTT only matters if the bot process itself is down, crashed, or\n        disconnected when a position needs to exit -- e.g. across the daily\n        token-refresh restart window, a VPS reboot, or a WS/process crash.\n\n        Deliberately does NOT assume a uniform _close_trade(trade, reason,\n        price) signature across strategies -- survivor.py, wave_extractor.py,\n        put_calendar.py, and nifty_gex.py all have different close-method\n        names and signatures (some track a list of open trades, some track\n        one active trade). Callers pass their own `on_failure` async callable\n        (typically a small lambda wrapping their own close method) so this\n        stays a thin, safe-to-reuse helper rather than forcing a large\n        cross-file signature refactor.\n\n        Returns True if a GTT was armed (or paper mode / broker doesn\'t\n        support GTTs, in which case there\'s nothing to arm and this is a\n        no-op success). Returns False if arming failed after retries --\n        callers should treat False as "this position currently has no\n        broker-side protection" and decide whether to auto-close or just\n        alert, via on_failure.\n        """\n        if self._is_paper or not hasattr(self.broker, "place_gtt_trailing_sl"):\n            return True\n\n        for attempt in range(2):\n            try:\n                gtt_id = await self.broker.place_gtt_trailing_sl(\n                    instrument_key=ikey,\n                    quantity=quantity,\n                    entry_price=entry_price,\n                    order_type=order_type,\n                    trailing_gap=trailing_gap,\n                    sl_pct=sl_pct,\n                )\n                if gtt_id:\n                    self._signal(f"🛡 GTT armed | {symbol} | id={gtt_id}")\n                    return True\n            except Exception as e:\n                logger.warning(f"[{self.name}] GTT arm attempt {attempt + 1} failed for {symbol}: {e}")\n            await asyncio.sleep(2)\n\n        logger.error(\n            f"[{self.name}] GTT arming FAILED after retries for {symbol} -- "\n            f"position has no broker-side protection."\n        )\n        try:\n            from core.alerting import alert_gtt_failed\n            alert_gtt_failed(symbol, "GTT failed after 2 attempts")\n        except Exception as e:\n            logger.error(f"[{self.name}] alert_gtt_failed itself failed: {e}")\n\n        if on_failure is not None:\n            try:\n                await on_failure()\n            except Exception as e:\n                logger.error(f"[{self.name}] on_failure callback (post-GTT-fail) raised: {e}")\n\n        return False', 'add _arm_broker_stop_loss helper')

